'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isAlmostSameValue = require( '@stdlib/assert/is-almost-same-value' );
var PINF = require( '@stdlib/constants/float64/pinf' );
var quantile = require( './../lib' );


// FIXTURES //

var data = require( './fixtures/python/data.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof quantile, 'function', 'main export is a function' );
	t.end();
});

tape( 'if any argument is NaN, the function returns NaN', function test( t ) {
	t.strictEqual( isnan( quantile( NaN, 1.0 ) ), true, 'returns expected value' );
	t.strictEqual( isnan( quantile( 0.5, NaN ) ), true, 'returns expected value' );
	t.end();
});

tape( 'if p is outside [0,1], the function returns NaN', function test( t ) {
	t.strictEqual( isnan( quantile( -0.1, 1.0 ) ), true, 'returns expected value' );
	t.strictEqual( isnan( quantile( 1.1, 1.0 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'if sigma < 0, the function returns NaN', function test( t ) {
	t.strictEqual( isnan( quantile( 0.5, -1.0 ) ), true, 'returns expected value' );
	t.end();
});

tape( 'if sigma = 0, the quantile is 0 for all p', function test( t ) {
	t.strictEqual( quantile( 0.0, 0.0 ), 0.0, 'returns expected value' );
	t.strictEqual( quantile( 0.5, 0.0 ), 0.0, 'returns expected value' );
	t.strictEqual( quantile( 1.0, 0.0 ), 0.0, 'returns expected value' );
	t.end();
});

tape( 'if p = 1, the function returns positive infinity', function test( t ) {
	t.strictEqual( quantile( 1.0, 1.0 ), PINF, 'returns expected value' );
	t.end();
});

tape( 'the function evaluates the half-normal quantile', function test( t ) {
	var expected;
	var sigma;
	var y;
	var i;
	var p;

	p = data.p;
	sigma = data.sigma;
	expected = data.expected;
	for ( i = 0; i < p.length; i++ ) {
		y = quantile( p[i], sigma[i] );
		if ( expected[i] !== null ) {
			t.strictEqual( isAlmostSameValue( y, expected[ i ], 40.0 ), true, 'within tolerance. p: '+p[ i ]+'. sigma: '+sigma[ i ]+'. y: '+y+'. expected: '+expected[ i ]+'.' );
		}
	}
	t.end();
});
